create table if not exists spiritual.tasbih_presets ( id bigint generated always as identity primary key, phrase text not null, transliteration text, translation text, default_count smallint not null default 33, category text default 'general' check (category in ('general', 'morning', 'evening', 'prayer', 'ramadan', 'custom')), sort_order smallint default 0 );
insert into spiritual.tasbih_presets (phrase, transliteration, translation, default_count, category, sort_order) values ('سُبْحَانَ اللَّهِ', 'SubhanAllah', 'Glory be to Allah', 33, 'general', 1), ('الْحَمْدُ لِلَّهِ', 'Alhamdulillah', 'Praise be to Allah', 33, 'general', 2), ('اللَّهُ أَكْبَرُ', 'Allahu Akbar', 'Allah is the Greatest', 34, 'general', 3), ('لَا إِلٰهَ إِلَّا اللَّهُ', 'La ilaha illAllah', 'There is no god but Allah', 100, 'general', 4), ('أَسْتَغْفِرُ اللَّهَ', 'Astaghfirullah', 'I seek forgiveness from Allah', 33, 'general', 5), ('سُبْحَانَ اللَّهِ وَبِحَمْدِهِ', 'SubhanAllahi wa bihamdihi', 'Glory be to Allah and His praise', 100, 'morning', 6), ('لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ', 'La hawla wa la quwwata illa billah', 'There is no power except from Allah', 100, 'general', 7) on conflict do nothing;
